WITH parsed AS (SELECT id, effective_from, currency, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ARRAY_MIN(tier_prices) AS lowest_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers WHERE YEAR(effective_from) >= 2023) SELECT DATE_TRUNC('MONTH', effective_from) AS activity_month, COUNT(DISTINCT currency) AS distinct_currencies, SIZE(COLLECT_SET(currency)) AS num_currencies FROM parsed GROUP BY DATE_TRUNC('MONTH', effective_from) ORDER BY distinct_currencies DESC
